package main
import("bytes";"encoding/json";"fmt";"go/ast";"go/parser";"go/token";"os";"path/filepath";"reflect";"slices";"strconv")
func normalized(n ast.Node)string{var b bytes.Buffer;err:=ast.Fprint(&b,token.NewFileSet(),n,func(name string,v reflect.Value)bool{if slices.Contains([]string{"Obj","Scope","Unresolved","Comments","Doc","Comment"},name){return false};return v.IsValid()&&v.Type()!=reflect.TypeOf(token.Pos(0))});if err!=nil{panic(err)};return b.String()}
func main(){root:=os.Args[1];before:=os.Args[2];var source struct{Family map[string][]string `json:"family_removals"`};raw,e:=os.ReadFile(os.Args[3]);if e!=nil{panic(e)};if e=json.Unmarshal(raw,&source);e!=nil{panic(e)};files:=map[string]string{"CategoryEditor":"plugins/categoryeditor/categoryeditor.go","TorrentTransfer":"plugins/torrenttransfer/plugin.go","SiteStatistic":"plugins/sitestatistic/plugin.go","MPServerStatus":"plugins/mpserverstatus/plugin.go","PluginUnInstall":"plugins/pluginuninstall/plugin.go","RemoveLink":"plugins/removelink/plugin.go"};counts:=map[string]int{}
 for id,path:=range files{old,e:=parser.ParseFile(token.NewFileSet(),filepath.Join(before,path),nil,parser.ParseComments);if e!=nil{panic(e)};new,e:=parser.ParseFile(token.NewFileSet(),filepath.Join(root,path),nil,parser.ParseComments);if e!=nil{panic(e)};removed:=[]string{};for _,decl:=range old.Decls{fn,ok:=decl.(*ast.FuncDecl);if !ok||fn.Name.Name!="Manifest"{continue};ast.Inspect(fn,func(n ast.Node)bool{kv,ok:=n.(*ast.KeyValueExpr);if !ok{return true};key,ok:=kv.Key.(*ast.Ident);if !ok||key.Name!="Methods"{return true};lit,ok:=kv.Value.(*ast.CompositeLit);if !ok{panic("Methods not literal")};next:=[]ast.Expr{};for _,x:=range lit.Elts{v,ok:=x.(*ast.BasicLit);if !ok{panic("nonliteral method")};name,e:=strconv.Unquote(v.Value);if e!=nil{panic(e)};if slices.Contains(source.Family[id],name){removed=append(removed,name)}else{next=append(next,x)}};lit.Elts=next;return false})};want:=slices.Clone(source.Family[id]);slices.Sort(want);slices.Sort(removed);if !slices.Equal(want,removed)||normalized(old)!=normalized(new){panic("unexpected production AST change "+path)};counts[id]=len(removed)};b,_:=json.Marshal(map[string]any{"exact_only_source_expected_methods_removed":true,"families":counts});fmt.Println(string(b))}
